MISSION0_DIALOGUE_PATCHES: tuple[InPlaceTextPatch, ...] = (InPlaceTextPatch(1333394, 'バーテン「いらっしゃいませ」', 'Bart: Welcome.', 'Mission 0 bartender greeting'), InPlaceTextPatch(1333432, 'バーテン「お客さん、この辺は初めてでしょう。', 'Bart: First time?', 'Mission 0 bartender newcomer question'), InPlaceTextPatch(1333477, 'いや、なに、顔を見りゃそれぐらいわかりますよ」', 'Your face gave it away.', 'Mission 0 bartender newcomer answer'), InPlaceTextPatch(1333531, 'バーテン「いったいどの辺から来なさったんです？\u3000おっと、つまらないこと聞いちまいましたね」', 'Bart: Where from? Never mind. Bad question.', 'Mission 0 bartender origin question'), InPlaceTextPatch(1333637, 'バーテン「ところで、あちらのお嬢さん、気を付けた方がいいですよ。どうも賞金稼ぎらしいですからね。ま、これは忠告ってやつです」', 'Bart: Watch that girl. Bounty hunter. Friendly warning.', 'Mission 0 bartender bounty hunter warning'), InPlaceTextPatch(1333767, 'バーテン「いやなに、わたしは最初からあんたも賞金稼ぎなんじゃないかと思ってたんですよ」', 'Bart: I knew you were a bounty hunter too.', 'Mission 0 bartender recognizes player'), InPlaceTextPatch(1333861, 'バーテン「ご注文は？」', 'Your order?', 'Mission 0 bartender order prompt'), InPlaceTextPatch(1333892, 'バーテン「無法地帯？\u3000とんでもない。ここにはここの法があるんですよ」', 'Lawless? No. We have our own law.', 'Mission 0 bartender law response'), InPlaceTextPatch(1333964, 'バーテン「この上の新市街にある茶色のビルがその本部でさあ」', 'HQ is in the brown building.', 'Mission 0 bartender headquarters response'), InPlaceTextPatch(1334026, 'バーテン「保安隊？\u3000命が惜しかったら、そんなことはかぎ回らないに限ると思いますがね」', 'Security? If you value life, do not ask.', 'Mission 0 bartender security response'), InPlaceTextPatch(1334114, 'バーテン「さあ、ちょっと知りませんね」', 'Bart: No idea.', 'Mission 0 bartender unknown response'), InPlaceTextPatch(1334156, '俺は少し待ってみることにした。', 'I waited a bit.', 'Mission 0 wait narration'), InPlaceTextPatch(1334187, '……だが何も起こらなかった。', 'Nothing.', 'Mission 0 wait result'), InPlaceTextPatch(1334230, 'バーテン「またどうぞ」', 'Come again.', 'Mission 0 bartender farewell'))


MISSION0_PROLOGUE_PATCHES: tuple[InPlaceTextPatch, ...] = (InPlaceTextPatch(1529898, '「俺の名はセンゴク、一匹狼の賞金稼ぎ。', 'Sengoku. Loner.', 'Mission 0 prologue introduction', wrap_width=PROLOGUE_WRAP_WIDTH), InPlaceTextPatch(1529937, 'ならず者の電脳犯罪者どもを片っ端から捕まえて警察に引き渡すのが俺の仕事だ。', 'I hunt crooks and turn them in.', 'Mission 0 opening narration job description', wrap_width=PROLOGUE_WRAP_WIDTH), InPlaceTextPatch(1530012, 'クリス・ダンフォード、コードネーム『バラ発疹』、', 'Danford aka Rose Rash,', 'Mission 0 prologue target name', wrap_width=PROLOGUE_WRAP_WIDTH), InPlaceTextPatch(1530061, 'こいつを追いかけて上海からＯＥＤＯに７年ぶりに舞い戻ってきた。', 'His trail led me back to Oedo.', 'Mission 0 prologue return to Oedo', wrap_width=PROLOGUE_WRAP_WIDTH), InPlaceTextPatch(1530124, 'だが、この７年の間に俺の知っていたＯＥＤＯ、特に犯罪者たちのたむろする旧市街はすっかり様子が変わってしまっていた。', 'Seven years changed Oedo. Old City most of all.', 'Mission 0 prologue changed city', wrap_width=PROLOGUE_WRAP_WIDTH), InPlaceTextPatch(1530239, '電警−電脳警察−の下部組織だった保安隊が勢力を増し、旧市街全体を飲み込もうとしている。', 'Security Force takes Old City.', 'Mission 0 prologue Security Force expansion', wrap_width=PROLOGUE_WRAP_WIDTH), InPlaceTextPatch(1530326, '街には武器が溢れ、以前よりずっと物騒な気配が漂っている。', "More guns. It's worse.", 'Mission 0 prologue dangerous streets', wrap_width=PROLOGUE_WRAP_WIDTH), InPlaceTextPatch(1530383, 'この世界最大の都市で何かが始まろうとしている。', 'It begins.', 'Mission 0 prologue impending event', wrap_width=PROLOGUE_WRAP_WIDTH), InPlaceTextPatch(1530430, '俺が仕掛けたワナをいつもすりぬけるＡ級の電脳犯罪者、', 'Top crooks evade me,', 'Mission 0 prologue rival criminals', wrap_width=PROLOGUE_WRAP_WIDTH), InPlaceTextPatch(1530483, '『ベンテン』と『ゴーグル』も、この街にやって来ているらしい。奴らの狙いは……？\u3000なにはともあれ調べてみるか」', "Benten. Goggles. Here. Why? I'll look.", 'Mission 0 prologue Benten and Goggles', wrap_width=PROLOGUE_WRAP_WIDTH))
